<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">                            $job//scalar[@dictRef=&#39;cp2k:status&#39;])[1])&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/&gt;</span></span>
